import { parse, ConfError } from './parser.js'
import { toJson, toKeys } from './output.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const input = readFileSync(0, 'utf8')
let root
try {
  root = parse(input)
} catch (e) {
  if (e instanceof ConfError) {
    process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
    process.exit(2)
  }
  throw e
}
process.stdout.write(args[0] === 'json' ? toJson(root) : toKeys(root))
