{"file_path":"src/output.js","content":"function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

function sortedKeys(node) {
  return [...node.map.keys()].sort(cmp)
}

function scalarJson(node) {
  if (node.t === 'integer') return node.v.toString()
  return JSON.stringify(node.v)
}

function emit(node, indent) {
  if (node.t === 'table') {
    const keys = sortedKeys(node)
    if (keys.length === 0) return '{}'
    const pad = '  '.repeat(indent + 1)
    const parts = keys.map((k) => `${pad}${JSON.stringify(k)}: ${emit(node.map.get(k), indent + 1)}`)
    return `{\n${parts.join(',\n')}\n${'  '.repeat(indent)}}`
  }
  if (node.t === 'array') {
    if (node.items.length === 0) return '[]'
    const pad = '  '.repeat(indent + 1)
    const parts = node.items.map((i) => pad + emit(i, indent + 1))
    return `[\n${parts.join(',\n')}\n${'  '.repeat(indent)}]`
  }
  return scalarJson(node)
}

export function toJson(root) {
  return emit(root, 0) + '\n'
}

export function toKeys(root) {
  const lines = []
  const visit = (node, path) => {
    if (node.t === 'table') {
      for (const k of sortedKeys(node)) {
        const p = path === '' ? k : `${path}.${k}`
        lines.push(`${p} ${node.map.get(k).t}`)
        visit(node.map.get(k), p)
      }
    } else if (node.t === 'array') {
      node.items.forEach((item, i) => {
        const p = `${path}[${i}]`
        lines.push(`${p} ${item.t}`)
        visit(item, p)
      })
    }
  }
  visit(root, '')
  return lines.map((l) => l + '\n').join('')
}
"}

{"file_path":"src/parser.js","content":"export class ConfError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

const isWs = (c) => c === ' ' || c === '\t'
const isComment = (c) => c === '#' || c === ';'
const isNameChar = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)

const newTable = () => ({ t: 'table', map: new Map(), headerDefined: false })

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class LineParser {
  constructor(text, line) {
    this.s = text
    this.i = 0
    this.line = line
  }

  err(msg) {
    return new ConfError(this.line, msg)
  }

  peek() {
    return this.s[this.i]
  }

  skipWs() {
    while (isWs(this.s[this.i])) this.i++
  }

  atEnd() {
    return this.i >= this.s.length || isComment(this.s[this.i])
  }

  // after skipWs: only end or comment may remain
  restIsEmpty() {
    this.skipWs()
    return this.atEnd()
  }

  parseQuoted(q) {
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.s.length) throw this.err('unterminated string')
      const c = this.s[this.i]
      if (c === q) {
        this.i++
        return out
      }
      if (q === '"' && c === '\\') {
        this.i++
        if (this.i >= this.s.length) throw this.err('unterminated string')
        const e = this.s[this.i]
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) {
          out += map[e]
          this.i++
        } else if (e === 'u') {
          const hex = this.s.slice(this.i + 1, this.i + 5)
          if (!/^[0-9A-Fa-f]{4}$/.test(hex)) throw this.err('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          this.i += 5
        } else {
          const cp = String.fromCodePoint(this.s.codePointAt(this.i))
          throw this.err(`invalid escape \\${cp}`)
        }
        continue
      }
      out += c
      this.i++
    }
  }

  parseName() {
    const c = this.peek()
    if (c === '"' || c === "'") return this.parseQuoted(c)
    const start = this.i
    while (isNameChar(this.s[this.i])) this.i++
    if (start === this.i) throw this.err('expected a name')
    return this.s.slice(start, this.i)
  }

  parseDotted() {
    const names = [this.parseName()]
    for (;;) {
      const save = this.i
      this.skipWs()
      if (this.peek() === '.') {
        this.i++
        this.skipWs()
        names.push(this.parseName())
      } else {
        this.i = save
        return names
      }
    }
  }

  parseValue(prefix) {
    this.skipWs()
    if (this.atEnd()) throw this.err('expected a value')
    const c = this.peek()
    if (c === ',' || c === ']' || c === '}') throw this.err('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.parseQuoted(c) }
    if (c === '[') return this.parseArray(prefix)
    if (c === '{') return this.parseInline(prefix)
    const start = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]}'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(start, this.i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    if (INT.test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    throw this.err(`invalid value ${w}`)
  }

  parseArray(prefix) {
    this.i++
    const items = []
    for (;;) {
      this.skipWs()
      if (this.atEnd()) throw this.err('unterminated array')
      if (this.peek() === ']') {
        this.i++
        return { t: 'array', items, aot: false }
      }
      items.push(this.parseValue(prefix))
      this.skipWs()
      if (this.atEnd()) throw this.err('unterminated array')
      const c = this.peek()
      if (c === ',') this.i++
      else if (c === ']') {
        this.i++
        return { t: 'array', items, aot: false }
      } else throw this.err('trailing text after a value')
    }
  }

  parseInline(prefix) {
    this.i++
    const table = newTable()
    this.skipWs()
    if (this.atEnd()) throw this.err('unterminated inline table')
    if (this.peek() === '}') {
      this.i++
      return table
    }
    for (;;) {
      this.skipWs()
      if (this.atEnd()) throw this.err('unterminated inline table')
      const names = this.parseDotted()
      this.skipWs()
      if (this.peek() !== '=') throw this.err('expected = in an inline table')
      this.i++
      const value = this.parseValue(prefix)
      this.assign(table, prefix, names, value)
      this.skipWs()
      if (this.atEnd()) throw this.err('unterminated inline table')
      const c = this.peek()
      if (c === ',') this.i++
      else if (c === '}') {
        this.i++
        return table
      } else throw this.err('trailing text after a value')
    }
  }

  // walk through names (all but the last), creating tables. Returns table.
  walk(table, prefix, names) {
    let path = prefix
    for (const n of names) {
      path = path === '' ? n : `${path}.${n}`
      let child = table.map.get(n)
      if (child === undefined) {
        child = newTable()
        table.map.set(n, child)
      } else if (child.t === 'array' && child.aot) {
        child = child.items[child.items.length - 1]
      } else if (child.t !== 'table') {
        throw this.err(`${path} is not a table`)
      }
      table = child
    }
    return { table, path }
  }

  assign(table, prefix, names, value) {
    const head = names.slice(0, -1)
    const last = names[names.length - 1]
    const w = this.walk(table, prefix, head)
    const path = w.path === '' ? last : `${w.path}.${last}`
    if (w.table.map.has(last)) throw this.err(`key ${path} is defined twice`)
    w.table.map.set(last, value)
  }
}

export function parse(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let current = root
  let currentPath = ''
  lines.forEach((text, idx) => {
    const p = new LineParser(text, idx + 1)
    p.skipWs()
    if (p.i >= text.length || isComment(text[p.i])) return
    if (text[p.i] === '[') {
      p.i++
      const isArr = p.peek() === '['
      if (isArr) p.i++
      p.skipWs()
      const names = p.parseDotted()
      p.skipWs()
      const close = (ch) => {
        if (p.peek() !== ch) throw p.err('unterminated table header')
        p.i++
      }
      close(']')
      if (isArr) close(']')
      if (!p.restIsEmpty()) throw p.err('trailing text after a table header')
      const head = names.slice(0, -1)
      const last = names[names.length - 1]
      const w = p.walk(root, '', head)
      const path = w.path === '' ? last : `${w.path}.${last}`
      const existing = w.table.map.get(last)
      if (isArr) {
        if (existing === undefined) {
          const arr = { t: 'array', items: [], aot: true }
          w.table.map.set(last, arr)
          current = newTable()
          current.headerDefined = true
          arr.items.push(current)
        } else if (existing.t === 'array' && existing.aot) {
          current = newTable()
          current.headerDefined = true
          existing.items.push(current)
        } else throw p.err(`${path} is not an array of tables`)
      } else {
        if (existing === undefined) {
          current = newTable()
          current.headerDefined = true
          w.table.map.set(last, current)
        } else if (existing.t === 'table') {
          if (existing.headerDefined) throw p.err(`table ${path} is defined twice`)
          existing.headerDefined = true
          current = existing
        } else throw p.err(`${path} is not a table`)
      }
      currentPath = path
      return
    }
    const names = p.parseDotted()
    p.skipWs()
    if (p.peek() !== '=') throw p.err('expected key = value')
    p.i++
    const value = p.parseValue(currentPath)
    if (!p.restIsEmpty()) throw p.err('trailing text after a value')
    p.assign(current, currentPath, names, value)
  })
  return root
}
"}

