{"file_path":"src/parser.js","content":"export class ParseError extends Error {}

const fail = (m) => { throw new ParseError(m) }
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
const isComment = (c) => c === '#' || c === ';'

const table = () => ({ t: 'table', map: new Map(), headed: false })
const join = (base, k) => (base === '' ? k : `${base}.${k}`)

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.c)) this.i++ }
  atEnd() { return this.i >= this.s.length || isComment(this.c) }
}

function quoted(L) {
  const q = L.c
  L.i++
  let out = ''
  for (;;) {
    if (L.i >= L.s.length) fail('unterminated string')
    const c = L.c
    if (c === q) { L.i++; return out }
    if (q === "'" || c !== '\\') { out += c; L.i++; continue }
    L.i++
    if (L.i >= L.s.length) fail('unterminated string')
    const e = L.c
    L.i++
    switch (e) {
      case '"': out += '"'; break
      case '\\': out += '\\'; break
      case 'n': out += '\n'; break
      case 't': out += '\t'; break
      case 'r': out += '\r'; break
      case '0': out += '\0'; break
      case 'u': {
        const h = L.s.slice(L.i, L.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        L.i += 4
        break
      }
      default: fail(`invalid escape \\${e}`)
    }
  }
}

function name(L) {
  const c = L.c
  if (c === '"' || c === "'") return quoted(L)
  if (!isBare(c)) fail('expected a name')
  const st = L.i
  while (isBare(L.c)) L.i++
  return L.s.slice(st, L.i)
}

function dotted(L) {
  const parts = [name(L)]
  for (;;) {
    const save = L.i
    L.ws()
    if (L.c !== '.') { L.i = save; return parts }
    L.i++
    L.ws()
    parts.push(name(L))
  }
}

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

function bare(L) {
  const st = L.i
  while (L.i < L.s.length && !isWs(L.c) && !',]};'.includes(L.c)) L.i++
  const w = L.s.slice(st, L.i)
  if (w === 'true') return { t: 'boolean', v: true }
  if (w === 'false') return { t: 'boolean', v: false }
  if (INT.test(w)) {
    const neg = w[0] === '-'
    const v = BigInt(w.replace(/^[+-]/, '').replaceAll('_', ''))
    return { t: 'integer', v: (neg && v !== 0n ? '-' : '') + v.toString() }
  }
  if (FLOAT.test(w)) return { t: 'float', v: parseFloat(w.replaceAll('_', '')) }
  fail(`invalid value ${w}`)
}

// Walk the dotted prefix from `cur`, creating tables; returns the table holding the last name.
function walk(cur, base, parts, notTable) {
  let path = base
  for (let i = 0; i < parts.length - 1; i++) {
    path = join(path, parts[i])
    let n = cur.map.get(parts[i])
    if (!n) { n = table(); cur.map.set(parts[i], n) }
    if (n.t === 'array' && n.aot) n = n.items[n.items.length - 1]
    else if (n.t !== 'table') fail(`${path} ${notTable}`)
    cur = n
  }
  return { cur, path: join(path, parts[parts.length - 1]) }
}

function assign(L, cur, base, inline) {
  const parts = dotted(L)
  L.ws()
  if (L.c !== '=') fail(inline ? 'expected = in an inline table' : 'expected key = value')
  L.i++
  const { cur: t, path } = walk(cur, base, parts, 'is not a table')
  const key = parts[parts.length - 1]
  if (t.map.has(key)) fail(`key ${path} is defined twice`)
  t.map.set(key, value(L, path))
}

function value(L, path) {
  L.ws()
  const c = L.c
  if (L.i >= L.s.length || isComment(c) || c === ',' || c === ']' || c === '}') fail('expected a value')
  if (c === '"' || c === "'") return { t: 'string', v: quoted(L) }
  if (c === '[') {
    L.i++
    const items = []
    for (;;) {
      L.ws()
      if (L.atEnd()) fail('unterminated array')
      if (L.c === ']') { L.i++; return { t: 'array', items, aot: false } }
      items.push(value(L, path))
      L.ws()
      if (L.c === ',') { L.i++; continue }
      if (L.c === ']') { L.i++; return { t: 'array', items, aot: false } }
      fail('unterminated array')
    }
  }
  if (c === '{') {
    L.i++
    const tbl = table()
    L.ws()
    if (L.c === '}') { L.i++; return tbl }
    for (;;) {
      L.ws()
      if (L.atEnd()) fail('unterminated inline table')
      assign(L, tbl, path, true)
      L.ws()
      if (L.c === ',') { L.i++; continue }
      if (L.c === '}') { L.i++; return tbl }
      fail('unterminated inline table')
    }
  }
  return bare(L)
}

function header(L, root) {
  L.i++
  const isArr = L.c === '['
  if (isArr) L.i++
  L.ws()
  const parts = dotted(L)
  L.ws()
  const close = (L.c === ']')
  if (!close) fail('unterminated table header')
  L.i++
  if (isArr) {
    if (L.c !== ']') fail('unterminated table header')
    L.i++
  }
  L.ws()
  if (!L.atEnd()) fail('trailing text after a table header')
  const { cur, path } = walk(root, '', parts, 'is not a table')
  const key = parts[parts.length - 1]
  const ex = cur.map.get(key)
  if (isArr) {
    if (!ex) {
      const arr = { t: 'array', items: [], aot: true }
      const nt = table()
      arr.items.push(nt)
      cur.map.set(key, arr)
      return { cur: nt, path }
    }
    if (ex.t !== 'array' || !ex.aot) fail(`${path} is not an array of tables`)
    const nt = table()
    ex.items.push(nt)
    return { cur: nt, path }
  }
  if (!ex) {
    const nt = table()
    nt.headed = true
    cur.map.set(key, nt)
    return { cur: nt, path }
  }
  if (ex.t !== 'table') fail(`${path} is not a table`)
  if (ex.headed) fail(`table ${path} is defined twice`)
  ex.headed = true
  return { cur: ex, path }
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const root = table()
  let cur = root
  let curPath = ''
  for (let n = 0; n < lines.length; n++) {
    const L = new Line(lines[n])
    try {
      L.ws()
      if (L.i >= L.s.length || isComment(L.c)) continue
      if (L.c === '[') {
        const r = header(L, root)
        cur = r.cur
        curPath = r.path
        continue
      }
      assign(L, cur, curPath, false)
      L.ws()
      if (!L.atEnd()) fail('trailing text after a value')
    } catch (e) {
      if (e instanceof ParseError) throw new ParseError(`line ${n + 1}: ${e.message}`)
      throw e
    }
  }
  return root
}
"}

