import { readFileSync } from 'node:fs'

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  const [, scheme, authority, path, query, fragment] = m
  return { scheme, authority, path, query, fragment }
}

function splitAuthority(a) {
  let userinfo
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); a = a.slice(at + 1) }
  const colon = a.indexOf(':', a.lastIndexOf(']') + 1)
  let host = a, port
  if (colon >= 0) { host = a.slice(0, colon); port = a.slice(colon + 1) }
  return { userinfo, host, port }
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}
const truncated = (s) => /%(?![0-9A-Fa-f]{2})/.test(s)
const lowerAscii = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

function removeDots(path) {
  let input = path, out = ''
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out = out.slice(0, Math.max(out.lastIndexOf('/'), 0))
    } else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out += seg
      input = input.slice(seg.length)
    }
  }
  return out
}

class Fail extends Error {}

function normalize(u, n) {
  let { scheme, authority, path, query, fragment } = u
  let ui, host, port
  if (authority !== undefined) ({ userinfo: ui, host, port } = splitAuthority(authority))
  const checks = [['path', path], ['userinfo', ui], ['host', host], ['query', query], ['fragment', fragment]]
  for (const [name, v] of checks) {
    if (v !== undefined && truncated(v)) throw new Fail(`error: line ${n}: the ${name} has a truncated percent-encoding`)
  }
  if (scheme !== undefined) scheme = lowerAscii(scheme)
  path = removeDots(pct(path))
  if (query !== undefined) query = pct(query)
  if (fragment !== undefined) fragment = pct(fragment)
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (authority !== undefined) {
    if (ui !== undefined) ui = pct(ui)
    host = lowerAscii(pct(host))
    if (port !== undefined) {
      port = pct(port)
      if (port === '' || (scheme !== undefined && DEFAULT_PORTS[scheme] === port)) port = undefined
    }
    out += '//' + (ui !== undefined ? ui + '@' : '') + host + (port !== undefined ? ':' + port : '')
    if (path === '') path = '/'
  }
  out += path
  if (query !== undefined) out += '?' + query
  if (fragment !== undefined) out += '#' + fragment
  return out
}

function resolve(base, ref) {
  let t
  if (ref.scheme !== undefined) {
    t = { ...ref, path: removeDots(ref.path) }
  } else if (ref.authority !== undefined) {
    t = { ...ref, scheme: base.scheme }
  } else if (ref.path === '') {
    t = { scheme: base.scheme, authority: base.authority, path: base.path,
      query: ref.query !== undefined ? ref.query : base.query, fragment: ref.fragment }
  } else {
    let path
    if (ref.path.startsWith('/')) path = ref.path
    else {
      let bp = base.path
      if (base.authority !== undefined && bp === '') bp = '/'
      const i = bp.lastIndexOf('/')
      path = (i >= 0 ? bp.slice(0, i + 1) : '') + ref.path
    }
    t = { scheme: base.scheme, authority: base.authority, path: removeDots(path), query: ref.query, fragment: ref.fragment }
  }
  return t
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const outs = []
  try {
    lines.forEach((line, idx) => {
      const n = idx + 1
      if (args[0] === 'normalize') { outs.push(normalize(parse(line), n)); return }
      const sp = line.indexOf(' ')
      if (sp < 0) throw new Fail(`error: line ${n}: expected a base and a reference`)
      const base = parse(line.slice(0, sp))
      if (base.scheme === undefined) throw new Fail(`error: line ${n}: the base has no scheme`)
      outs.push(normalize(resolve(base, parse(line.slice(sp + 1))), n))
    })
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
  process.stdout.write(outs.map((o) => o + '\n').join(''))
}
main()
