import { readFileSync } from 'node:fs'

const NAME = /^[A-Za-z0-9_./:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    const fail = (r) => { throw new Fail(`error: line ${i + 1}: ${r}`) }
    const num = (field, v, least) => {
      if (!UINT.test(v) || BigInt(v) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const d = t[0]
    if (d === 'bucket' || d === 'window') {
      const bucket = d === 'bucket'
      if (t.length !== (bucket ? 5 : 4)) {
        fail(bucket ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
      }
      if (events.length) fail('declarations must come before the first event')
      if (!NAME.test(t[1])) fail(`invalid policy name ${t[1]}`)
      let p
      if (bucket) {
        const capacity = num('capacity', t[2], 1)
        const refill = num('refill', t[3], 0)
        const per = num('per', t[4], 1)
        p = { type: 'bucket', name: t[1], capacity, refill, per }
      } else {
        const limit = num('limit', t[2], 0)
        const span = num('span', t[3], 1)
        p = { type: 'window', name: t[1], limit, span }
      }
      if (policies.has(t[1])) fail(`policy ${t[1]} is declared twice`)
      policies.set(t[1], p)
    } else if (d === 'route') {
      if (t.length < 3) fail('expected route <prefix> <policy>...')
      if (events.length) fail('declarations must come before the first event')
      if (!NAME.test(t[1])) fail(`invalid route prefix ${t[1]}`)
      if (routes.has(t[1])) fail(`prefix ${t[1]} is routed twice`)
      for (const n of t.slice(2)) if (!policies.has(n)) fail(`unknown policy ${n}`)
      routes.set(t[1], t.slice(2).map((n) => policies.get(n)))
    } else if (d === 'event') {
      if (t.length !== 3) fail('expected event <tick> <key>')
      const tick = num('tick', t[1], 0)
      if (!NAME.test(t[2])) fail(`invalid key ${t[2]}`)
      if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      events.push({ tick, key: t[2] })
    } else fail(`unknown directive ${d}`)
  })
  return { routes, events }
}

function run(mode, text) {
  const { routes, events } = parse(text)
  const states = new Map() // policy name + key -> state
  const stats = new Map()
  const out = []
  let ta = 0
  let td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const [prefix, ps] of routes) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
    }
    let denier = null
    if (best !== null) {
      const ps = routes.get(best)
      const sts = ps.map((p) => {
        const id = p.name + '\0' + key
        let s = states.get(id)
        if (!s) {
          s = p.type === 'bucket' ? { tokens: p.capacity * p.per, last: tick } : { ticks: [] }
          states.set(id, s)
        }
        if (p.type === 'bucket') {
          const cap = p.capacity * p.per
          s.tokens += p.refill * (tick - s.last)
          if (s.tokens > cap) s.tokens = cap
          s.last = tick
        } else {
          const cutoff = tick - p.span
          s.ticks = s.ticks.filter((x) => x > cutoff)
        }
        return s
      })
      for (let i = 0; i < ps.length && denier === null; i++) {
        const p = ps[i]
        const s = sts[i]
        const ok = p.type === 'bucket' ? s.tokens >= p.per : BigInt(s.ticks.length) < p.limit
        if (!ok) denier = p.name
      }
      if (denier === null) {
        ps.forEach((p, i) => {
          if (p.type === 'bucket') sts[i].tokens -= p.per
          else sts[i].ticks.push(tick)
        })
      }
    }
    const st = stats.get(key) || { a: 0, d: 0 }
    stats.set(key, st)
    if (denier === null) { st.a++; ta++; out.push(`${tick} ${key} allow`) } else { st.d++; td++; out.push(`${tick} ${key} deny ${denier}`) }
  }
  if (mode === 'replay') return out
  const res = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)).map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
  res.push(`total allowed=${ta} denied=${td}`)
  return res
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}
try {
  const lines = run(args[0], readFileSync(0, 'utf8'))
  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}
EOF
