import { parseFormula } from './parse.js'
import { Sheet, formatValue } from './eval.js'
import { parseAddress, colIndex } from './addr.js'

const fail = (msg) => { process.stderr.write(msg + '\n'); process.exit(2) }
const args = process.argv.slice(2)
