const cells = new Map()
lines.forEach((raw, i) => {
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^([^ \t]*)[ \t]*([^]*)$/.exec(line)
  const addr = parseAddress(m[1])
  if (!addr) fail(`error: line ${i + 1}: invalid cell address ${m[1]}`)
  if (cells.has(addr.key)) fail(`error: line ${i + 1}: cell ${addr.key} is declared twice`)
  cells.set(addr.key, { addr, content: m[2] })
})
const sorted = [...cells.values()].sort((a, b) => colIndex(a.addr.col) - colIndex(b.addr.col) || a.addr.row - b.addr.row)
let out = ''
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const c of sorted) out += `${c.addr.key}=${formatValue(sheet.get(c.addr.key))}\n`
} else {
  for (const c of sorted) {
    let s = c.addr.key + ':'
    if (c.content[0] === '=') {
      const p = parseFormula(c.content.slice(1))
      if (p.ok) for (const k of p.deps) s += ' ' + k
    }
    out += s + '\n'
  }
}
process.stdout.write(out)
