import { parseAddress, colIndex, colName } from './addr.js'

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[=<>+\-*/^(),:])/.exec(s.slice(i)))) { toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue }
    return null
  }
  return toks
}

export function rangeCells(a, b) {
  const c1 = colIndex(a.col), c2 = colIndex(b.col)
  const out = []
  for (let c = Math.min(c1, c2); c <= Math.max(c1, c2); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(colName(c) + r)
  return out
}

export function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return { ok: false }
  let p = 0
  const deps = new Set()
  let misplaced = false
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const bad = new Error('syntax')

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { t: 'un', op, e: unary() } }
    return primary()
  }
  function ref(word) {
    const a = parseAddress(word)
    if (a) deps.add(a.key)
    return a
  }
  function primary() {
    if (p >= toks.length) throw bad
    const tk = toks[p++]
    if (tk.t === 'num') return { t: 'num', v: tk.v }
    if (tk.t === 'op') {
      if (tk.v !== '(') throw bad
      const e = cmp()
      if (!isOp(')')) throw bad
      p++
      return { t: 'paren', e }
    }
    const up = tk.v.toUpperCase()
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) p++
      else {
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw bad
        }
      }
      for (const a of args) if (a.t === 'range') a.direct = true
      return { t: 'call', name: up, args }
    }
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].t !== 'word') throw bad
      const w2 = toks[p++].v
      const a = ref(tk.v), b = ref(w2)
      if (a && b) for (const k of rangeCells(a, b)) deps.add(k)
      return { t: 'range', a, b }
    }
    if (up === 'TRUE') return { t: 'bool', v: true }
    if (up === 'FALSE') return { t: 'bool', v: false }
