    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[=<>+\-*/^(),:])/.exec(s.slice(i)))) { toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue }
    return null
  }
  return toks
}

export function rangeCells(a, b) {
  const c1 = colIndex(a.col), c2 = colIndex(b.col)
  const out = []
  for (let c = Math.min(c1, c2); c <= Math.max(c1, c2); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(colName(c) + r)
  return out
