import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdentStart = (c) => isLetter(c) || c === '_'
const isIdentChar = (c) => isIdentStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const advance = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = (Math.floor((col - 1) / 4) + 1) * 4 + 1
    else col++
    return c
  }

  while (i < n) {
    const c = cs[i]
    const sl = line
    const sc = col
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { advance(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') advance()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      advance(); advance()
      let depth = 1
      while (depth > 0) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { advance(); advance(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { advance(); advance(); depth-- }
        else advance()
      }
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      advance(); advance()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = advance()
        if (d === '"') break
        v += d
      }
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(v) })
      continue
    }
    if (isIdentStart(c)) {
      let s = ''
      while (i < n && isIdentChar(cs[i])) s += advance()
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(s) ? 'keyword' : 'ident', body: s })
      continue
    }
    if (isDigit(c)) {
      let s = ''
      let bad = false
      const take = () => { s += advance() }
      // digit run with single underscores between digits; returns count of digits
      const run = (ok) => {
        let count = 0
        while (i < n) {
          if (ok(cs[i])) { take(); count++ }
          else if (cs[i] === '_' && count > 0 && ok(cs[i + 1])) take()
          else break
        }
        return count
      }
      const p = cs[i + 1]
      const radix = c === '0' ? { x: isHex, X: isHex, b: (d) => d === '0' || d === '1', B: (d) => d === '0' || d === '1', o: (d) => d >= '0' && d <= '7' && d.length === 1, O: (d) => d !== undefined && d >= '0' && d <= '7' }[p] : undefined
      if (radix) {
        take(); take()
        const ok = (d) => d !== undefined && radix(d)
        if (run(ok) === 0) bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { take(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1])) { take(); run(isDigit) }
          else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) { take(); take(); run(isDigit) }
        }
      }
      if (i < n && isIdentChar(cs[i])) {
        bad = true
        while (i < n && isIdentChar(cs[i])) take()
      }
