      tokens.push({ line: sl, col: sc, kind: 'number', body: s })
      continue
    }
    if (c === '"') {
      advance()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const el = line
        const ec = col
        const d = cs[i]
        if (d === '\n') throw new ScanError(el, ec, 'newline in string')
        advance()
        if (d === '"') break
        if (d !== '\\') { v += d; continue }
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = advance()
        const invalid = () => new ScanError(el, ec, `invalid escape \\${e}`)
