        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const el = line
        const ec = col
        const d = cs[i]
        if (d === '\n') throw new ScanError(el, ec, 'newline in string')
        advance()
        if (d === '"') break
        if (d !== '\\') { v += d; continue }
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = advance()
        const invalid = () => new ScanError(el, ec, `invalid escape \\${e}`)
        if (e === 'n') v += '\n'
        else if (e === 't') v += '\t'
        else if (e === 'r') v += '\r'
        else if (e === '\\') v += '\\'
        else if (e === '"') v += '"'
        else if (e === '0') v += '\0'
        else if (e === 'x') {
          if (!isHex(cs[i]) || !isHex(cs[i + 1])) throw invalid()
          v += String.fromCharCode(parseInt(advance() + advance(), 16))
        } else if (e === 'u') {
          if (cs[i] !== '{') throw invalid()
          let j = i + 1
          let h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (!h || cs[j] !== '}' || parseInt(h, 16) > 0x10ffff) throw invalid()
          while (i <= j) advance()
          v += String.fromCodePoint(parseInt(h, 16))
        } else throw invalid()
      }
      tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(v) })
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    const p = PUNCT.find((x) => x === two) ?? PUNCT.find((x) => x === c)
    if (p) {
      for (let k = 0; k < p.length; k++) advance()
      tokens.push({ line: sl, col: sc, kind: 'punct', body: p })
      continue
    }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
const input = readFileSync(0).toString('utf8')
let tokens
try {
  tokens = scan(input)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
let out = ''
if (args[0] === 'tokens') {
  for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
} else {
  for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
EOF
