  for (const k of names) out += `${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}\n`
  out += `total ${total}\n`
} else {
  const prio = new Map()
  const rev = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const d of sdeps.get(k)) rev.get(d).push(k)
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
