  const done = new Map() // name -> finish
  let t = 0n, left = names.length, mk = 0n
  while (left > 0) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      const task = order.find((k) => !done.has(k) && sdeps.get(k).every((d) => done.has(d) && done.get(d) <= t))
      if (task === undefined) break
