}

export function normalizeRecord(line) {
  return finish(parse(line))
}

export function resolveRecord(line) {
  const sp = line.indexOf(' ')
  if (sp < 0) throw new UriError('expected a base and a reference')
  const base = parse(line.slice(0, sp))
  const ref = parse(line.slice(sp + 1))
  if (base.scheme === undefined) throw new UriError('the base has no scheme')
  let t
  if (ref.scheme !== undefined) t = { ...ref, path: removeDots(ref.path) }
  else if (ref.authority !== undefined) {
    t = { ...ref, scheme: base.scheme, path: removeDots(ref.path) }
  } else if (ref.path === '') {
    t = { scheme: base.scheme, authority: base.authority, path: base.path,
      query: ref.query !== undefined ? ref.query : base.query, fragment: ref.fragment }
  } else {
    let path
    if (ref.path.startsWith('/')) path = ref.path
    else if (base.authority !== undefined && base.path === '') path = '/' + ref.path
    else path = base.path.slice(0, base.path.lastIndexOf('/') + 1) + ref.path
    t = { scheme: base.scheme, authority: base.authority, path: removeDots(path),
      query: ref.query, fragment: ref.fragment }
  }
  return finish(t)
}
