import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let names = null
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  const e = (m) => fail(`error: line ${n}: ${m}`)
  if (t[0] === 'candidates') {
    if (names !== null || ballots.length) e('candidates must be declared once, before any ballot')
    if (t.length < 2) e('expected candidates <name>...')
    const seen = new Set()
    for (const nm of t.slice(1)) {
      if (!NAME.test(nm)) e(`invalid candidate name ${nm}`)
      if (seen.has(nm)) e(`candidate ${nm} is declared twice`)
      seen.add(nm)
    }
    names = t.slice(1)
  } else if (t[0] === 'ballot') {
    if (names === null) e('candidates must be declared once, before any ballot')
    if (t.length < 3) e('expected ballot <count> <candidate>...')
    if (!/^[1-9][0-9]*$/.test(t[1])) e('count must be a positive integer')
    const seen = new Set()
    for (const nm of t.slice(2)) {
      if (!names.includes(nm)) e(`unknown candidate ${nm}`)
      if (seen.has(nm)) e(`candidate ${nm} is repeated`)
      seen.add(nm)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else e(`unknown directive ${t[0]}`)
})
if (names === null) fail('error: no candidates')

const cont = new Set(names)
const history = []
const out = []
let winner = null
for (;;) {
  const counts = new Map([...cont].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => cont.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  let total = 0n
  for (const b of ballots) total += b.count
  history.push(counts)
  const list = [...counts.entries()].sort((a, b) =>
    a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)
  let line = `round ${history.length}: ` + list.map(([c, v]) => `${c}=${v}`).join(' ')
  line += ` exhausted=${total - active}`
  out.push(line)
  if (active === 0n) break
  const top = list[0]
  if (top[1] * 2n > active) { winner = top[0]; break }
  let min = list[list.length - 1][1]
  let tied = list.filter(([, v]) => v === min).map(([c]) => c)
  while (tied.length > 1) {
    let next = null
    for (const h of history) {
      const vals = tied.map((c) => h.get(c))
      const m = vals.reduce((a, b) => (a < b ? a : b))
      if (vals.some((v) => v !== m)) { next = tied.filter((c) => h.get(c) === m); break }
    }
    if (!next) break
    tied = next
  }
  const el = tied.reduce((a, b) => (a > b ? a : b))
  cont.delete(el)
  out.push(`eliminated ${el}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${history.length}\n${end}\n`)
