export function parseElection(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  let seenBallot = false
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    if (t[0] === 'candidates') {
      if (candidates !== null || seenBallot) fail(n, 'candidates must be declared once, before any ballot')
      if (t.length < 2) fail(n, 'expected candidates <name>...')
      const names = []
      for (const name of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(n, `invalid candidate name ${name}`)
        if (names.includes(name)) fail(n, `candidate ${name} is declared twice`)
        names.push(name)
      }
      candidates = names
    } else if (t[0] === 'ballot') {
      if (candidates === null) fail(n, 'candidates must be declared once, before any ballot')
      seenBallot = true
      if (t.length < 3) fail(n, 'expected ballot <count> <candidate>...')
      if (!/^[1-9][0-9]*$/.test(t[1])) fail(n, 'count must be a positive integer')
      const rank = []
      for (const name of t.slice(2)) {
        if (!candidates.includes(name)) fail(n, `unknown candidate ${name}`)
        if (rank.includes(name)) fail(n, `candidate ${name} is repeated`)
        rank.push(name)
      }
