      const m = vals.reduce((a, b) => (b < a ? b : a))
      if (vals.some((v) => v !== m)) tied = tied.filter((c) => r.counts.get(c) === m)
    }
    tied.sort()
    const out = tied[tied.length - 1]
    continuing.delete(out)
    round.eliminated = out
  }
