function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const res = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) res.push({ who, bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return res
}

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mode, mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const parts = [] // {kind, lines} or {kind:'conflict', m, b, t}
  let pos = 0, k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    if (rs > pos) parts.push({ kind: 'stable', lines: base.slice(pos, rs) })
    pos = re
    if (group.length === 1) {
      const c = group[0]
      parts.push(c.who === 0
        ? { kind: 'mine', lines: mine.slice(c.ss, c.se) }
        : { kind: 'theirs', lines: theirs.slice(c.ss, c.se) })
      continue
    }
    const baseL = base.slice(rs, re)
    const side = (who, doc) => {
      const cs = group.filter(c => c.who === who)
      if (!cs.length) return baseL
      const first = cs[0], last = cs[cs.length - 1]
      const minS = Math.min(...cs.map(c => c.bs)), maxE = Math.max(...cs.map(c => c.be))
      return doc.slice(first.ss - (minS - rs), last.se + (re - maxE))
    }
    const m = side(0, mine), t = side(1, theirs)
    if (same(m, t)) parts.push({ kind: 'both', lines: m })
    else if (same(m, baseL)) parts.push({ kind: 'theirs', lines: t })
    else if (same(t, baseL)) parts.push({ kind: 'mine', lines: m })
    else parts.push({ kind: 'conflict', m, b: baseL, t })
  }
  if (pos < base.length) parts.push({ kind: 'stable', lines: base.slice(pos) })
  const out = []
  let conflict = false
  for (const p of parts) {
    if (p.kind === 'conflict') conflict = true
    if (mode === 'regions') {
      if (p.kind === 'conflict') out.push(`conflict mine=${p.m.length} base=${p.b.length} theirs=${p.t.length}`)
      else out.push(`${p.kind} ${p.lines.length}`)
    } else if (p.kind === 'conflict') {
      out.push('<<<<<<< mine', ...p.m)
      if (mode === 'merge') out.push('||||||| base', ...p.b)
      out.push('=======', ...p.t, '>>>>>>> theirs')
    } else out.push(...p.lines)
  }
  return { out, conflict }
}
