      const minS = Math.min(...cs.map(c => c.bs)), maxE = Math.max(...cs.map(c => c.be))
      return doc.slice(first.ss - (minS - rs), last.se + (re - maxE))
    }
    const m = side(0, mine), t = side(1, theirs)
    if (same(m, t)) parts.push({ kind: 'both', lines: m })
    else if (same(m, baseL)) parts.push({ kind: 'theirs', lines: t })
    else if (same(t, baseL)) parts.push({ kind: 'mine', lines: m })
    else parts.push({ kind: 'conflict', m, b: baseL, t })
  }
  if (pos < base.length) parts.push({ kind: 'stable', lines: base.slice(pos) })
  const out = []
  let conflict = false
  for (const p of parts) {
    if (p.kind === 'conflict') conflict = true
    if (mode === 'regions') {
      if (p.kind === 'conflict') out.push(`conflict mine=${p.m.length} base=${p.b.length} theirs=${p.t.length}`)
      else out.push(`${p.kind} ${p.lines.length}`)
    } else if (p.kind === 'conflict') {
      out.push('<<<<<<< mine', ...p.m)
      if (mode === 'merge') out.push('||||||| base', ...p.b)
      out.push('=======', ...p.t, '>>>>>>> theirs')
    } else out.push(...p.lines)
  }
  return { out, conflict }
}
