{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'

const fail = (msg) => {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) fail('error: usage: cli.js values|deps')
const mode = args[0]

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

// ---- parse sheet
const cells = new Map() // key "A1" -> {col,row,addr,content}
const colIndex = (s) => (s.length === 1 ? s.charCodeAt(0) - 64 : (s.charCodeAt(0) - 64) * 26 + s.charCodeAt(1) - 64)
const ADDR = /^([A-Za-z]{1,2})([0-9]{1,3})$/
function parseAddr(w) {
  const m = ADDR.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  return { col: colIndex(letters), row, key: letters + row }
}
lines.forEach((raw, i) => {
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
  const w = m[1]
  const a = parseAddr(w)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${w}`)
  if (cells.has(a.key)) fail(`error: line ${i + 1}: cell ${a.key} is declared twice`)
  // content: verbatim after one run of spaces/tabs
  const content = line.slice(w.length).replace(/^[ \t]+/, '')
  cells.set(a.key, { ...a, content })
})

// ---- formula parser
class ParseError extends Error {}
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ t: 'word', v: m[0].toUpperCase() }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(s.slice(i)))) { toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue }
    throw new ParseError()
  }
  return toks
}

function parseFormula(src) {
  const toks = tokenize(src)
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v
  const next = () => toks[p++]
  let misplaced = false
  const CMP = ['=', '<>', '<', '<=', '>', '>=']
  function cmp() {
    let l = add()
    while (peek() && peek().t === 'op' && CMP.includes(peek().v)) { const op = next().v; l = { k: 'bin', op, l, r: add() } }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = next().v; l = { k: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = next().v; l = { k: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { next(); return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = next().v; return { k: 'un', op, e: unary() } }
    return primary(false)
  }
  function primary(argPos) {
    const t = next()
    if (!t) throw new ParseError()
    if (t.t === 'num') return { k: 'num', v: t.v }
    if (t.t === 'op' && t.v === '(') {
      const e = cmp()
      if (!isOp(')')) throw new ParseError()
      next()
      return e
